from collections import Counter, defaultdict
from fractions import Fraction as F
from math import gcd, lcm, sqrt
import json

def sub(a, b):
    return tuple((x - y for x, y in zip(a, b)))

def dot(a, b):
    return sum((x * y for x, y in zip(a, b)), F(0))

def cross(a, b):
    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])

def primitive(v):
    denominator = lcm(*(x.denominator for x in v))
    values = tuple((int(x * denominator) for x in v))
    divisor = gcd(*values)
    if not divisor:
        raise ValueError('zero normal')
    return tuple((x // divisor for x in values))

def component_analysis(name, vertices, triangles):
    normals, planes = ([], [])
    edges = defaultdict(list)
    for index, face in enumerate(triangles):
        if len(face) != 3 or len(set(face)) != 3 or any((i < 0 or i >= len(vertices) for i in face)):
            raise ValueError('invalid triangle')
        a, b, c = (vertices[i] for i in face)
        normal = primitive(cross(sub(b, a), sub(c, a)))
        normals.append(normal)
        planes.append((normal, dot(a, normal)))
        for i, j in zip(face, face[1:] + face[:1]):
            edges[tuple(sorted((i, j)))].append((index, i, j))
    if any((len(rows) > 2 for rows in edges.values())):
        raise ValueError('nonmanifold source edge')
    adjacent = defaultdict(set)
    for rows in edges.values():
        if len(rows) == 2:
            (a, i, j), (b, k, l) = rows
            if planes[a] == planes[b]:
                if (i, j) != (l, k):
                    raise ValueError('inconsistent coplanar winding')
                adjacent[a].add(b)
                adjacent[b].add(a)
    remaining = set(range(len(triangles)))
    result = []
    while remaining:
        seed = min(remaining)
        stack, group = ([seed], set())
        while stack:
            index = stack.pop()
            if index in group:
                continue
            group.add(index)
            stack.extend(adjacent[index] - group)
        remaining -= group
        boundary = []
        vector_area = [F(0), F(0), F(0)]
        for index in sorted(group):
            face = triangles[index]
            a, b, c = (vertices[i] for i in face)
            face_cross = cross(sub(b, a), sub(c, a))
            vector_area = [x + y / 2 for x, y in zip(vector_area, face_cross)]
            for i, j in zip(face, face[1:] + face[:1]):
                if sum((row[0] in group for row in edges[tuple(sorted((i, j)))])) == 1:
                    boundary.append((i, j))
        outgoing = dict(boundary)
        if len(outgoing) != len(boundary) or Counter((j for _, j in boundary)) != Counter((i for i, _ in boundary)):
            raise ValueError('invalid boundary cycle')
        unvisited = set(outgoing)
        loops = []
        while unvisited:
            initial = min(unvisited)
            loop, current = ([], initial)
            while current not in loop:
                loop.append(current)
                unvisited.remove(current)
                current = outgoing[current]
            if current != initial:
                raise ValueError('nonclosing boundary')
            changed = True
            while changed and len(loop) > 3:
                changed = False
                for i in range(len(loop)):
                    p, q, r = (vertices[loop[j % len(loop)]] for j in (i - 1, i, i + 1))
                    if cross(sub(q, p), sub(r, q)) == (0, 0, 0) and dot(sub(q, p), sub(r, q)) > 0:
                        del loop[i]
                        changed = True
                        break
            loops.append(loop)
        rectangular = False
        if len(loops) == 1 and len(loops[0]) == 4:
            corners = [vertices[i] for i in loops[0]]
            sides = [sub(corners[(i + 1) % 4], corners[i]) for i in range(4)]
            rectangular = sides[0] == tuple((-x for x in sides[2])) and sides[1] == tuple((-x for x in sides[3])) and (dot(sides[0], sides[1]) == 0)
            if rectangular and dot(vector_area, vector_area) != dot(sides[0], sides[0]) * dot(sides[1], sides[1]):
                raise ValueError('rectangle area/topology mismatch')
        area_squared = dot(vector_area, vector_area)
        nx, ny, nz = normals[seed]
        area_in_domain = F(1, 128) ** 2 <= area_squared <= F(1, 32) ** 2
        normal_in_domain = nz > 0 and 16 * nz * nz >= 9 * (nx * nx + ny * ny + nz * nz)
        used_vertices = sorted({i for index in group for i in triangles[index]})
        bounds = [[min((vertices[i][axis] for i in used_vertices)) for axis in range(3)], [max((vertices[i][axis] for i in used_vertices)) for axis in range(3)]]
        result.append({'object_name': name, 'source_triangle_indices': sorted(group), 'vertex_indices': used_vertices, 'plane_normal_integer': list(normals[seed]), 'plane_offset': planes[seed][1], 'boundary_loops': loops, 'rectangle_supported': rectangular, 'area_squared_m4': area_squared, 'area_in_domain': area_in_domain, 'normal_nz_in_domain': normal_in_domain, 'eligible': rectangular and area_in_domain and normal_in_domain, 'bounds_world_m': bounds, 'center_world_m': [(a + b) / 2 for a, b in zip(*bounds)]})
    return result

def clip(polygon, distances):
    output = []
    for index, a in enumerate(polygon):
        b = polygon[(index + 1) % len(polygon)]
        da, db = (distances[index], distances[(index + 1) % len(polygon)])
        if da >= 0:
            output.append(a)
        if da < 0 < db or db < 0 < da:
            ratio = da / (da - db)
            output.append(tuple((x + ratio * (y - x) for x, y in zip(a, b))))
    return output

def area2(polygon):
    if not polygon:
        return F(0)
    return abs(sum((a[0] * b[1] - a[1] * b[0] for a, b in zip(polygon, polygon[1:] + polygon[:1]))))

def prove(objects, region, direction):
    target = next((obj for obj in objects if obj['name'] == region['object_name']))
    indices = region['boundary_loops'][0]
    a, b, _, e = [target['vertices'][index] for index in indices]
    u, v = (sub(b, a), sub(e, a))
    normal = tuple((F(value) for value in region['plane_normal_integer']))
    denominator = dot(normal, direction)
    if denominator <= 0:
        raise ValueError('witness_view_not_oriented_front')
    uu, vv = (dot(u, u), dot(v, v))
    proofs = []
    for obj in objects:
        for index, face in enumerate(obj['triangles']):
            if obj['name'] == target['name'] and index in region['source_triangle_indices']:
                continue
            points = [obj['vertices'][vertex] for vertex in face]
            times = [dot(normal, sub(point, a)) / denominator for point in points]
            if max(times) <= 0:
                proofs.append(dict(object_name=obj['name'], triangle=index, reason='no_positive_front_depth'))
                continue
            positive = clip(points, times)
            projected = []
            for point in positive:
                time = dot(normal, sub(point, a)) / denominator
                plane_point = tuple((x - time * d for x, d in zip(point, direction)))
                relative = sub(plane_point, a)
                projected.append((dot(relative, u) / uu, dot(relative, v) / vv))
            for axis, bound, sign in ((0, F(0), 1), (0, F(1), -1), (1, F(0), 1), (1, F(1), -1)):
                if projected:
                    projected = clip(projected, [sign * (point[axis] - bound) for point in projected])
            overlap = area2(projected)
            if overlap:
                raise ValueError('positive_area_front_occluder/' + obj['name'] + '/' + str(index))
            proofs.append(dict(object_name=obj['name'], triangle=index, reason='zero_area_positive_front_projection'))
    return dict(whole_rectangle_geometrically_complete=True, front_dot_product=str(denominator), world_direction=list(direction), occluder_triangles_checked=len(proofs), method='Fraction front halfspace clipping, directional projection to target plane, rectangle intersection area', proofs=proofs)

